/* ============================================
   SITE HEADER
   The site's top bar: brand, section pills with
   mega menus, actions, and a drawer once folded
   ============================================ */

@layer rift.tokens, rift.preset, rift.components;

@layer rift.components {

/* Base */
.ds-site-header {
  /* The bar's height. An override hook: the blur's reach and a page's own
     anchor offsets read it. */
  --ds-site-header-height: calc(var(--control-height-default) + var(--padding-1000));
  /* How far the blur dissolves below the bar. */
  --ds-site-header-blur-reach: var(--gap-1500);
  position: relative;
  /* Lifts the open panel over the page's flow when the header is not sticky. */
  z-index: 1;
  width: 100%;
}

/* Sticky: rides up with whatever sits above it, then holds at the top. */
.ds-site-header--sticky {
  position: sticky;
  top: 0;
  z-index: var(--layer-sticky);
}

/* The blur stack, viewport-fixed (a sticky box is not a containing block
   for it) so it spans the full width whatever the host's gutters. It sits
   inside the header's stacking context, behind the bar's controls. Never a
   filter on the header itself: that would make the header a backdrop root
   and the mega menu's own glass would sample only the header's subtree. */
.ds-site-header__blur.ds-progressive-blur {
  position: fixed;
  inset: 0 0 auto;
  height: calc(var(--ds-site-header-height) + var(--ds-site-header-blur-reach));
  z-index: -1;
}

/* Behind an open menu on a full-width bar, a second progressive blur: the
   window's width from the top down past the menu's bottom edge (its height
   measured into --ds-site-header-menu-height as it opens), dissolving below
   it, so the menu floats over a softened page rather than a hard band. It
   sits with the bar's own blur, behind the bar and the menu, and only a
   full-width bar shows it; a contained bar's menu needs no help. */
.ds-site-header__menu-blur.ds-progressive-blur {
  position: fixed;
  inset: 0 0 auto;
  height: calc(
    var(--ds-site-header-height) + var(--gap-200) + var(--ds-site-header-menu-height, 0px) +
      var(--ds-site-header-blur-reach) * 2
  );
  z-index: -1;
  display: none;
  opacity: 0;
  visibility: hidden;
  transition:
    opacity var(--motion-duration-slow) var(--motion-ease-standard),
    visibility 0s linear var(--motion-duration-slow);
}

.ds-site-header[data-ds-width='full'] .ds-site-header__menu-blur.ds-progressive-blur,
:where([data-ds-width='full']) > .ds-site-header:not([data-ds-width]) .ds-site-header__menu-blur.ds-progressive-blur {
  display: block;
}

.ds-site-header__menu-blur.ds-progressive-blur[data-open] {
  opacity: 1;
  visibility: visible;
  transition:
    opacity var(--motion-duration-slow) var(--motion-ease-standard),
    visibility 0s;
}

/* The bar: brand, pills, then the end cluster pushed to the far side. */
.ds-site-header__bar {
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--gap-400);
  height: var(--ds-site-header-height);
  box-sizing: border-box;
  /* The folded bar keeps its pills out of flow at full width so they stay
     measurable; clipping the inline axis keeps them from widening the page
     into a sideways scroll. The margin leaves room for a focus ring at the
     bar's edge, and the block axis stays open for the menu panel. */
  overflow-x: clip;
  overflow-clip-margin: var(--gap-200);
}

/* A set width (the shell recipe's width axis): the bar takes the side
   gutter, and contained centres it at the contained width so it lines up
   with a contained page; full leaves the maximum at none. */
.ds-site-header--width .ds-site-header__bar {
  max-width: var(--ds-shell-content-max, var(--ds-shell-contained-width));
  margin-inline: auto;
  padding-inline: var(--ds-shell-gutter);
  /* The bar's side padding, read by the menu panel so it lines up with
     the bar's content rather than its outer edge. */
  --_bar-inset: var(--ds-shell-gutter);
}

.ds-site-header__brand {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}

/* The pills sit beside the brand rather than centred on the page:
   --gap-1000 from the brand (the bar's own gap plus this margin), and the
   first pill's inline padding sets the rest of the visual gap. */
.ds-site-header__nav {
  display: flex;
  align-items: center;
  gap: var(--gap-100);
  margin-inline-start: calc(var(--gap-1000) - var(--gap-400));
  flex-shrink: 0;
}

.ds-site-header__end {
  display: flex;
  align-items: center;
  gap: var(--gap-400);
  margin-inline-start: auto;
  flex-shrink: 0;
}

.ds-site-header__actions,
.ds-site-header__wide-actions {
  display: flex;
  align-items: center;
  gap: var(--gap-400);
  flex-shrink: 0;
}

.ds-site-header__section {
  position: relative;
}

/* Pills: a pill-radius link at the compact control height, so a caret's
   icon box never makes one pill taller than its neighbours. */
.ds-site-header__pill {
  display: inline-flex;
  align-items: center;
  gap: var(--gap-050);
  height: var(--control-height-compact);
  box-sizing: border-box;
  padding-inline: var(--padding-400);
  border-radius: var(--radius-pill);
  background-color: transparent;
  color: var(--color-text-primary);
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
  line-height: 1;
  white-space: nowrap;
  text-decoration: none;
  transition:
    background-color var(--motion-duration-fast) var(--motion-ease-standard),
    color var(--motion-duration-fast) var(--motion-ease-standard);
}

/* Hover is the tertiary family's wash, as on a tertiary Button, a NavList
   row and the MegaMenu's rows: a container fill can match the page floor
   in a light theme and vanish. */
.ds-site-header__pill:hover {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-site-header__pill:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
}

/* An open menu holds the hover fill and nothing more: opening a menu is
   not a selection. Declared before --current so the current section keeps
   its colour while its menu is open. */
.ds-site-header__pill--open {
  background-color: var(--color-action-passive-bg-hover);
}

/* The current section is the selected item of an exclusive set, so it
   takes the action selection pair, SegmentedControl's active segment; a
   neutral fill would read as the hover state over the glassy blur. */
.ds-site-header__pill--current {
  background-color: var(--color-action-primary-bg);
  color: var(--color-action-primary-text);
}

.ds-site-header__pill--current:hover {
  background-color: var(--color-action-primary-bg-hover);
}

.ds-site-header__caret {
  --icon-size: var(--icon-size-500);
  line-height: 1;
  color: var(--color-text-secondary);
  transition: rotate var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-site-header__pill--current .ds-site-header__caret {
  color: inherit;
}

.ds-site-header__pill--open .ds-site-header__caret {
  rotate: 180deg;
}

/* The menu button only exists once the bar folds. It wears the track
   recipe the CommandPaletteTrigger, the ThemePicker's trigger and the
   ThemeToggle's cycle circle wear (container fill, hairline border, the
   track's curve), so the circles at the bar's end read as one set, and it
   hovers as they do: the fill steps up, the glyph holds its colour. */
.ds-site-header__menu-button {
  display: none;
}

.ds-site-header .ds-site-header__menu-button {
  background-color: var(--color-bg-container-primary);
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: calc(var(--radius-pill) + var(--padding-100));
}

.ds-site-header .ds-site-header__menu-button:not(.ds-icon-button--disabled):hover {
  background-color: var(--color-bg-container-secondary);
}

.ds-site-header .ds-site-header__menu-button .ds-icon-button__icon,
.ds-site-header .ds-site-header__menu-button:not(.ds-icon-button--disabled):hover .ds-icon-button__icon,
.ds-site-header .ds-site-header__menu-button:not(.ds-icon-button--disabled):active .ds-icon-button__icon {
  color: var(--color-action-icon-default);
}

/* While the drawer is open its close button stands in this exact spot, on
   the top layer; the button underneath would only show through the scrim. */
.ds-site-header__menu-button--hidden {
  visibility: hidden;
}

/* The mega menu hangs under the bar across the bar's content, inside its
   side padding, so its edges meet the brand and the last action and the
   page's content below. It is not anchored to a control
   (useAnchoredPosition's job): it belongs to the bar and spans it, so it
   rides the bar's own box.
   The wrapper keeps the height of the last section shown after the menu
   closes, so it never takes a press itself: a transparent box that size
   would sit over the page and swallow its clicks. Only the menu does, and a
   closed menu is hidden, which takes it out of hit testing too. */
.ds-site-header__panel {
  position: absolute;
  inset-block-start: calc(100% + var(--gap-200));
  inset-inline: var(--_bar-inset, 0px);
  pointer-events: none;
}

.ds-site-header__panel > .ds-mega-menu {
  pointer-events: auto;
}

/* The hover bridge. Between a pill and its menu lie the bar's lower padding
   and the gap the menu hangs by, and neither is the pill nor the menu: a
   pointer that took longer than the hide delay to cross them lost the menu
   on the way, and the press landed on the page. While a menu is open the
   wrapper holds that strip too, so the way down never leaves the menu. It
   stays inside the bar's padding, clear of every control in the row. */
.ds-site-header__panel:has(> .ds-mega-menu--open)::before {
  content: '';
  position: absolute;
  inset-inline: 0;
  inset-block-end: 100%;
  block-size: calc(var(--gap-200) + var(--padding-1000) / 2);
  pointer-events: auto;
}

/* A full-width bar wider than the contained width keeps its menu at the
   contained width and opens it where the reader is looking: the panel
   starts under the section pills (--ds-site-header-nav-start, measured as
   it opens), runs at most the shell recipe's contained width, and never
   comes closer to the window's end than the side padding, so a wide window
   neither stretches the menu's columns apart nor strands it in the middle.
   On a bar no wider than --ds-site-header-menu-hang-from (an override
   hook, the contained width by default; a host whose contained layout is
   wider than its full one's step sets it to that wider width), where a
   full bar and a contained one draw the same, the menu does the same as a
   contained bar's and spans the bar's content: the clamp below is a step,
   zero up to that width and the pills' offset past it. Full comes from the
   header's own width or, unset, from the width of the slot it sits in
   (SiteLayout's header slot). */
.ds-site-header[data-ds-width='full'] .ds-site-header__panel,
:where([data-ds-width='full']) > .ds-site-header:not([data-ds-width]) .ds-site-header__panel {
  /* --ds-site-header-nav-start is measured onto the header as the menu
     opens, not a hook; the fallback covers the frame before it is. */
  --_panel-start: calc(
    var(--_bar-inset, 0px) +
      clamp(
        0px,
        (100% - var(--ds-site-header-menu-hang-from, var(--ds-shell-contained-width, 100%))) * 1000,
        var(--ds-site-header-nav-start, var(--_bar-inset, 0px)) - var(--_bar-inset, 0px)
      )
  );
  inset-inline: var(--_panel-start) auto;
  /* The contained-width cap holds only while the menu hangs from the
     pills; up to the hang width the cap steps out of the way (the same
     step, inverted), so the menu meets the bar's far edge as a contained
     bar's does. */
  width: min(
    calc(
      var(--ds-shell-contained-width, 100%) +
        clamp(
          0px,
          (var(--ds-site-header-menu-hang-from, var(--ds-shell-contained-width, 100%)) - 100% + 1px) * 1000,
          100vw
        )
    ),
    calc(100% - var(--_panel-start) - var(--_bar-inset, 0px))
  );
}

/* Condensed: `condensedActions` take the place of `actions`. Whichever set
   is not showing leaves the row but stays measurable (hidden, out of flow,
   inert), as the folded pills do. */
.ds-site-header--condensed .ds-site-header__actions:not(.ds-site-header__actions--condensed),
.ds-site-header:not(.ds-site-header--condensed) .ds-site-header__actions--condensed {
  position: absolute;
  visibility: hidden;
  pointer-events: none;
}

/* Folded: the pills and the wide actions leave the row but stay measurable
   (hidden, out of flow, inert), and the menu button takes their place. */
.ds-site-header--folded .ds-site-header__nav,
.ds-site-header--folded .ds-site-header__wide-actions {
  position: absolute;
  visibility: hidden;
  pointer-events: none;
}

.ds-site-header--folded .ds-site-header__menu-button {
  display: inline-flex;
}

.ds-site-header--folded .ds-site-header__panel {
  display: none;
}

/* Before the bar has measured itself (the first frame, which a
   server-rendered page shows before its script runs), it folds by CSS below
   the `initialFold` step, with `condensedActions` in place of `actions`, so
   a phone never sees the pills spill past the actions. The first measurement replaces this in the same commit as
   hydration. */
@media (max-width: 959px) {
  .ds-site-header--prefold-tablet .ds-site-header__nav,
  .ds-site-header--prefold-tablet .ds-site-header__wide-actions {
    position: absolute;
    visibility: hidden;
    pointer-events: none;
  }

  .ds-site-header--prefold-tablet .ds-site-header__menu-button {
    display: inline-flex;
  }

  .ds-site-header--prefold-tablet .ds-site-header__actions:not(.ds-site-header__actions--condensed) {
    position: absolute;
    visibility: hidden;
    pointer-events: none;
  }

  .ds-site-header.ds-site-header--prefold-tablet .ds-site-header__actions--condensed {
    position: static;
    visibility: visible;
    pointer-events: auto;
  }
}

@media (max-width: 1279px) {
  .ds-site-header--prefold-mid .ds-site-header__nav,
  .ds-site-header--prefold-mid .ds-site-header__wide-actions {
    position: absolute;
    visibility: hidden;
    pointer-events: none;
  }

  .ds-site-header--prefold-mid .ds-site-header__menu-button {
    display: inline-flex;
  }

  .ds-site-header--prefold-mid .ds-site-header__actions:not(.ds-site-header__actions--condensed) {
    position: absolute;
    visibility: hidden;
    pointer-events: none;
  }

  .ds-site-header.ds-site-header--prefold-mid .ds-site-header__actions--condensed {
    position: static;
    visibility: visible;
    pointer-events: auto;
  }
}

/* The drawer: its brand row lands on the bar's own brand. SiteHeader
   measures the bar as the drawer opens (its top, which is 0 once stuck and
   the host's gutter at rest, and its inline start) and the panel takes
   those as its padding, with the header row the bar's height, so the
   panel slides in under a brand that does not move. */
.ds-site-header__drawer .ds-drawer__panel {
  width: min(320px, 80vw);
  padding-block-start: var(--ds-site-header-drawer-top, var(--padding-500));
  padding-inline-start: var(--ds-site-header-drawer-start, var(--padding-500));
  /* The floating glass the command palette wears, so the page reaches
     through the menu frosted rather than behind an opaque sheet. The
     panel lets its close button out (below); its body still scrolls. */
  background-color: var(--color-bg-glass);
  backdrop-filter: blur(24px);
  overflow: visible;
}

/* The drawer's close button swaps with the menu button: it sits on the
   scrim exactly where the menu button was (measured as the drawer opens),
   and fades in once the panel has slid home, so the X never travels with
   it. It stays the drawer's own button, inside its focus trap. */
.ds-site-header__drawer .ds-drawer__close {
  position: absolute;
  inset-block-start: var(--ds-site-header-close-top, var(--padding-500));
  inset-inline-start: var(--ds-site-header-close-start, auto);
  /* The menu button's compact box, so the close lands exactly on it. */
  width: var(--control-height-compact);
  height: var(--control-height-compact);
  /* ds-allow(color): on-scrim furniture, as Lightbox's: the scrim is dark in both themes, so the glyph is white in both. */
  color: #ffffff;
  opacity: 0;
  transition: opacity var(--motion-duration-fast) var(--motion-ease-standard);
}

/* The glyph at the menu button's own size, so the swap reads as one icon
   turning into another. */
.ds-site-header__drawer .ds-drawer__close .material-symbols-rounded {
  --icon-size: var(--icon-size-600);
  /* The glyph takes the close's on-scrim white, not IconButton's
     icon colour, which is dark in light mode and vanished on the scrim. */
  color: inherit;
}

.ds-site-header__drawer .ds-drawer__panel[data-state="open"] .ds-drawer__close {
  opacity: 1;
  transition-delay: var(--motion-duration-slow);
}

.ds-site-header__drawer .ds-drawer__close:hover {
  /* ds-allow(color): the hover wash on the always-dark scrim, as Lightbox's controls. */
  background-color: rgba(255, 255, 255, 0.15);
}

/* The footer row starts under the brand, not at the panel's far edge. */
.ds-site-header__drawer .ds-drawer__footer {
  justify-content: flex-start;
}

.ds-site-header__drawer .ds-drawer__header {
  align-items: center;
  height: var(--ds-site-header-height, auto);
}

.ds-site-header__drawer-brand {
  display: flex;
  align-items: center;
}

/* The drawer's scroll area hangs out by the stack's row inset, so the
   fills sit in the gutter and every label lands on the brand's start
   line. The scroll area itself moves, not the stack inside it, so nothing
   overflows it sideways. */
.ds-site-header__drawer .ds-drawer__body {
  margin-inline: calc(-1 * var(--padding-300));
  padding-inline: 0;
  overflow-x: hidden;
}

/* On a phone the drawer is the whole screen: a solid sheet under a bar that
   keeps the header's seat (the brand where it was, the close where the menu
   button was), clear of the notch and the home indicator. Glass would put
   the page's words behind the menu's, so the sheet is the page surface. */
@media (max-width: 719px) {
  /* The drawer's own size rule names three classes; this names as many. */
  .ds-site-header__drawer.ds-drawer .ds-drawer__panel {
    width: 100%;
    max-width: none;
    border-radius: 0;
    background-color: var(--color-bg-page-primary);
    backdrop-filter: none;
    padding-block-start: max(var(--ds-site-header-drawer-top, var(--padding-500)), env(safe-area-inset-top));
    padding-block-end: max(var(--padding-500), calc(env(safe-area-inset-bottom) + var(--padding-200)));
  }

  /* No scrim shows beside a full sheet, so the close takes the page's ink. */
  .ds-site-header__drawer .ds-drawer__close {
    color: var(--color-icon-primary);
  }

  .ds-site-header__drawer .ds-drawer__close:hover {
    background-color: var(--color-action-passive-bg-hover);
  }

  /* The pinned footer runs the sheet's width, its action full width. */
  .ds-site-header__drawer .ds-drawer__footer {
    padding-block-start: var(--padding-300);
    border-block-start: var(--border-025) solid var(--color-divider);
  }
}

/* The list does the scrolling, as NavList's scrollable mode: no scrollbar
   until it moves and its ends fading out, the sidebar's treatment, so the
   drawer's body only gives it the height. */
.ds-site-header__drawer .ds-drawer__body {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* Icon side padding, Button's rule: a section with a mega menu trails a
   caret, whose box carries its own side bearing, so that pill's end takes
   the step below the label side (16 → 12). */
.ds-site-header__pill:has(.ds-site-header__caret) {
  padding-inline-end: var(--padding-300);
}

} /* @layer rift.components */

'use client';

import React, { useCallback, useEffect, useId, useLayoutEffect, useRef, useState } from 'react';
import { useLinkComponent, type LinkComponent } from '../../behaviors/LinkProvider';
import { useLayer } from '../../behaviors/useLayer';
import { isRtl } from '../../behaviors/direction';
import { BREAKPOINT_MID_PX, BREAKPOINT_TABLET_PX, mediaBelow } from '../../tokens/breakpoints';
import { MOTION_HOVER_HIDE_DELAY_MS } from '../../tokens/motion';
import { IconButton } from '../IconButton/IconButton';
import { Drawer } from '../Drawer/Drawer';
import { MegaMenu, type MegaMenuItem, type MegaMenuShowcase } from '../MegaMenu/MegaMenu';
import { NavStack, type NavStackEntry, type NavStackItem } from '../NavStack/NavStack';
import { navStackPathTo } from '../NavStack/path';
import { ProgressiveBlur } from '../ProgressiveBlur/ProgressiveBlur';
import '../../behaviors/shell.css';
import './SiteHeader.css';
import '../../fonts/material-symbols.css';

/**
 * A page in a section's drawer level. One with `items` drills into a level
 * of its own (a category of pages), opening with an overview row to `href`.
 */
export interface SiteHeaderDrawerItem {
  /** Where the row links; on a row with `items`, the overview row's destination. */
  href: string;
  /** Row text. */
  label: string;
  /** A second line under the label. */
  description?: string;
  /** Icon before the label: a Material Symbol name or a custom element. */
  icon?: string | React.ReactNode;
  /** The pages on the level this row opens. */
  items?: SiteHeaderDrawerItem[];
}

/** One top-level section of the site: a pill in the bar, a row in the drawer. */
export interface SiteHeaderSection {
  /** A stable key for the section. */
  id: string;
  /** The pill's text. */
  label: string;
  /** The section's landing page: where a click on the pill goes. */
  href: string;
  /**
   * A mega menu for the section. Hovering or focusing the pill opens it; its
   * items are also the section's sub-list in the drawer.
   */
  mega?: {
    /** The panel's link rows. */
    items: MegaMenuItem[];
    /** A featured card beside the rows. */
    showcase?: MegaMenuShowcase;
  };
  /**
   * The section's sub-list in the drawer, when it should differ from its
   * menu's items: a page that needs a wide screen, say, left out of the
   * drawer that only narrow screens see. Defaults to the menu's items.
   */
  drawerItems?: SiteHeaderDrawerItem[];
  /**
   * Marks the section as the one being viewed. Left unset, the header works
   * it out from `currentHref`: the section's own page, a page under it, or
   * any page its menu lists.
   */
  current?: boolean;
}

/** Props owned by SiteHeader itself — everything else falls through to the `<header>`. */
type SiteHeaderOwnProps = {
  /**
   * The brand at the bar's start, usually a logo linking home. Rendered as
   * given, so it carries its own link.
   */
  brand?: React.ReactNode;
  /** The site's top-level sections, in order. */
  sections: SiteHeaderSection[];
  /** The path of the page being viewed, used to mark the current section, row and drawer item. */
  currentHref?: string;
  /** Controls at the bar's end that stay at every width, such as a search button; `condensedActions`, when given, stand in for them on the condensed step. */
  actions?: React.ReactNode;
  /**
   * The same controls drawn narrower, such as an icon-only CommandPaletteTrigger and a
   * `cycle` ThemeToggle. When the full row stops fitting, these take the place of
   * `actions` (the header adds `ds-site-header--condensed`), and the pills fold to the
   * menu button only when the condensed row does not fit either. Without it the
   * header folds as soon as the full row stops fitting.
   */
  condensedActions?: React.ReactNode;
  /**
   * Controls at the bar's end that show only while the pills fit, such as a
   * Get started button. Once the bar folds to its menu button they leave it; put
   * their drawer twin in `drawerFooter`.
   */
  wideActions?: React.ReactNode;
  /** Content for the drawer's footer, such as the controls `wideActions` holds in the bar. It shows on the drawer's first level only: a level the reader drilled into leaves it out. */
  drawerFooter?: React.ReactNode;
  /** Content above the drawer's first level of rows, such as a search field. It leaves when the reader drills in. */
  drawerHeader?: React.ReactNode;
  /**
   * More of the drawer's first level, after the sections: rows and sections
   * of NavStack entries, such as a row that drills into a site's resources
   * or a group of settings that drill into their choices.
   */
  drawerEntries?: NavStackEntry[];
  /** Whether the folded bar's drawer is open, for a host that owns that state. Pair with `onDrawerOpenChange`. */
  drawerOpen?: boolean;
  /** Whether the drawer starts open, when the header owns its state. */
  defaultDrawerOpen?: boolean;
  /** Called when the drawer opens or closes, controlled or not. */
  onDrawerOpenChange?: (open: boolean) => void;
  /**
   * Where the bar folds before it has measured itself: on the first frame,
   * which a server-rendered page shows before its script runs. Below this
   * breakpoint (`tablet` or the wider `mid`) the bar starts folded by CSS
   * alone, so a phone never sees the pills overflow; the measurement takes
   * over once the script runs. Pick the step nearest where the pills stop
   * fitting, or `never` for a bar that fits at every width. Defaults to
   * `foldBelow` when that is set, so a bar told to fold at a step starts
   * folded there too and never shifts when its script runs.
   * @default foldBelow ?? 'tablet'
   */
  initialFold?: 'tablet' | 'mid' | 'never';
  /**
   * Fold the bar into its menu at or below this breakpoint even when the
   * pills would fit (`tablet` is 959px and below, `mid` 1279px), for a site
   * whose sidebar of pages leaves the page there: the menu then carries the
   * pages (each section's `drawerItems`), so the reader always has one way
   * in. Leave it out to fold only when the row runs out of room.
   * @default undefined
   */
  foldBelow?: 'tablet' | 'mid';
  /**
   * Whether the header sticks to the top of the viewport over a progressive
   * blur. Off, it scrolls away with the page and draws no blur.
   */
  sticky?: boolean;
  /**
   * How far, in pixels, the page scrolls before the page-surface tint fades
   * in over the sticky header's blur.
   */
  tintAfter?: number;
  /**
   * The component every link renders through, so a router's link (Next.js
   * `Link`) navigates without a reload. Falls back to the nearest
   * `LinkProvider`, then `<a>`.
   */
  linkComponent?: LinkComponent;
  /** The accessible name of the section links' `<nav>` landmark. */
  navLabel?: string;
  /** The accessible name of the menu button that opens the drawer. */
  drawerOpenLabel?: string;
  /**
   * The drawer's title, naming the dialog. Shown at its top when there is no
   * `brand`; with one, the brand takes its place and the title is read only
   * by assistive tech.
   */
  drawerTitle?: string;
  /** The accessible name of the drawer's close button. */
  drawerCloseLabel?: string;
  /**
   * How wide the bar's contents run, read from the shell recipe's width
   * axis. `contained` centres them in the contained width (1440px, or the
   * nearest `--ds-shell-contained-width`) with the side gutter, lining up
   * with a contained page below; `full` runs them edge to edge, the gutter
   * aside. Leave it out and the bar fills whatever box the host gives it,
   * with no gutter of its own; inside a SiteLayout it follows the layout's
   * `headerWidth` instead.
   * @default undefined
   */
  width?: 'contained' | 'full';
  /** Additional CSS classes on the `<header>`. */
  className?: string;
};

export interface SiteHeaderProps
  extends SiteHeaderOwnProps,
    Omit<React.ComponentPropsWithRef<'header'>, keyof SiteHeaderOwnProps> {}

const isUnder = (href: string, currentHref?: string) =>
  currentHref != null && (currentHref === href || currentHref.startsWith(`${href}/`));

const sectionIsCurrent = (section: SiteHeaderSection, currentHref?: string) =>
  section.current ??
  (isUnder(section.href, currentHref) ||
    (section.mega?.items.some((item) => isUnder(item.href, currentHref)) ?? false));

/**
 * A site's top bar: the brand, a pill per section with a mega menu on any
 * section that has one, and actions at the end, sticking to the viewport
 * over a progressive blur whose tint arrives once the page scrolls. When
 * the pills no longer fit, measured on the bar's own width rather than the
 * viewport's, the bar folds to a menu button that opens a drawer of the
 * same sections. The forwarded ref and any unrecognised props target the
 * `<header>`.
 */
export function SiteHeader({
  brand,
  sections,
  currentHref,
  actions,
  condensedActions,
  wideActions,
  drawerFooter,
  drawerHeader,
  drawerEntries,
  drawerOpen: drawerOpenProp,
  defaultDrawerOpen = false,
  onDrawerOpenChange,
  foldBelow,
  initialFold = foldBelow ?? 'tablet',
  sticky = true,
  tintAfter = 48,
  linkComponent,
  navLabel = 'Primary',
  drawerOpenLabel = 'Open menu',
  drawerTitle = 'Menu',
  drawerCloseLabel = 'Close menu',
  width,
  className = '',
  ref,
  ...rest
}: SiteHeaderProps) {
  const Link = useLinkComponent(linkComponent);
  const baseClass = 'ds-site-header';
  const panelId = useId();

  const headerRef = useRef<HTMLElement | null>(null);
  const barRef = useRef<HTMLDivElement>(null);
  const brandRef = useRef<HTMLDivElement>(null);
  const navRef = useRef<HTMLElement>(null);
  const wideRef = useRef<HTMLDivElement>(null);
  const actionsRef = useRef<HTMLDivElement>(null);
  const condensedActionsRef = useRef<HTMLDivElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const menuButtonRef = useRef<HTMLButtonElement>(null);
  const closeTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  // Set while Escape hands focus back to a pill, so that focus does not
  // reopen the panel it just closed.
  const returningFocus = useRef(false);
  // The page scrollbar's width as the drawer opened. The drawer's scroll lock
  // takes the scrollbar away and widens the bar by that much; measured
  // against the wider bar, a header within a scrollbar of its fold would
  // unfold, close the drawer, get its scrollbar back and fold again.
  const lockedGutter = useRef(0);

  const [openId, setOpenId] = useState<string | null>(null);
  // The section whose content the panel holds. It outlives openId, so a
  // closing panel fades out with its rows still in it rather than empty.
  const [shownId, setShownId] = useState<string | null>(null);
  const [condensed, setCondensed] = useState(false);
  const [folded, setFolded] = useState(false);
  // False until the first measurement: the CSS fold stands in until then.
  const [measured, setMeasured] = useState(false);
  // The bar's place when the drawer opened, so the drawer's brand row lands
  // on the bar's own brand whatever the scroll, the gutter or the direction.
  const [drawerOffset, setDrawerOffset] = useState<React.CSSProperties>({});
  const [tinted, setTinted] = useState(false);
  const [drawerOpenState, setDrawerOpenState] = useState(defaultDrawerOpen);
  const drawerOpen = drawerOpenProp ?? drawerOpenState;
  /* How deep the drawer's menu is. The footer (a site's call to action)
     belongs to the first level, the index of the site; a level the reader
     drilled into is about that section, so the footer steps aside there.
     Every open starts on the first level. */
  // How deep the drawer's stack is; null until the reader steps, while it
  // sits on the level it opened on (the current page's).
  const [drawerDepth, setDrawerDepth] = useState<number | null>(null);
  const setDrawerOpen = useCallback(
    (next: boolean) => {
      setDrawerDepth(null);
      lockedGutter.current = next ? window.innerWidth - document.documentElement.clientWidth : 0;
      if (drawerOpenProp === undefined) setDrawerOpenState(next);
      onDrawerOpenChange?.(next);
    },
    [drawerOpenProp, onDrawerOpenChange],
  );

  const setRef = (node: HTMLElement | null) => {
    headerRef.current = node;
    if (typeof ref === 'function') ref(node);
    else if (ref) ref.current = node;
  };

  // The fold: the room the full row needs against the room the bar has.
  // Folded pills stay in the DOM, hidden and out of flow, so they keep
  // their width for the next measurement; so do whichever of `actions` and
  // `condensedActions` is not showing. The row is measured with each set,
  // so the actions condense before the pills fold, and state changes only
  // when an answer flips, never per resize frame.
  useLayoutEffect(() => {
    const bar = barRef.current;
    if (!bar) return;
    const measure = () => {
      const barStyle = getComputedStyle(bar);
      const gap = parseFloat(barStyle.columnGap) || 0;
      // clientWidth counts the bar's own inline padding (the shell gutter
      // a full-width bar carries), which the row can never use.
      const padding =
        (parseFloat(barStyle.paddingInlineStart) || 0) + (parseFloat(barStyle.paddingInlineEnd) || 0);
      const navStart = navRef.current ? parseFloat(getComputedStyle(navRef.current).marginInlineStart) || 0 : 0;
      const rowWidth = (actionsEl: HTMLElement | null) => {
        const parts = [brandRef.current, navRef.current, wideRef.current, actionsEl];
        const widths = parts.map((el) => (el ? el.scrollWidth : 0));
        const present = widths.filter((w) => w > 0).length;
        return widths.reduce((sum, w) => sum + w, 0) + navStart + gap * Math.max(present - 1, 0);
      };
      const room = bar.clientWidth - padding - lockedGutter.current;
      const full = rowWidth(actionsRef.current);
      const tight = condensedActionsRef.current ? rowWidth(condensedActionsRef.current) : full;
      const forced =
        foldBelow !== undefined &&
        window.matchMedia(mediaBelow(foldBelow === 'mid' ? BREAKPOINT_MID_PX : BREAKPOINT_TABLET_PX)).matches;
      setCondensed(condensedActionsRef.current != null && (forced || full > room));
      setFolded(forced || tight > room);
      setMeasured(true);
    };
    measure();
    const observer = new ResizeObserver(measure);
    [
      bar,
      brandRef.current,
      navRef.current,
      wideRef.current,
      actionsRef.current,
      condensedActionsRef.current,
    ].forEach((el) => el && observer.observe(el));
    return () => observer.disconnect();
  }, [sections, actions, condensedActions, wideActions, brand, foldBelow]);

  // The tint over the sticky blur follows the page's scroll past `tintAfter`.
  useEffect(() => {
    if (!sticky) return;
    let frame = 0;
    const check = () => {
      frame = 0;
      setTinted(window.scrollY > tintAfter);
    };
    const onScroll = () => {
      if (!frame) frame = requestAnimationFrame(check);
    };
    check();
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => {
      window.removeEventListener('scroll', onScroll);
      if (frame) cancelAnimationFrame(frame);
    };
  }, [sticky, tintAfter]);

  useEffect(() => () => clearTimeout(closeTimer.current), []);

  // As the drawer opens, measure where the bar and its menu button sit, so
  // the drawer's brand row lands on the bar's brand and its close button on
  // the menu button it replaces, whatever the scroll, the gutter or the
  // reading direction. Measured on open, not live: a scroll event mid-open
  // (iOS fires them as the scroll lock engages) must not move the X.
  const placeDrawer = useCallback(() => {
    const bar = barRef.current;
    if (!bar) return;
    const rtl = isRtl(bar);
    const start = (rect: DOMRect) => (rtl ? document.documentElement.clientWidth - rect.right : rect.left);
    const barRect = bar.getBoundingClientRect();
    // The bar's own start padding (its gutter, when `width` is set) is where
    // its brand actually starts, so the drawer's brand lands on it.
    const inset = parseFloat(getComputedStyle(bar).paddingInlineStart) || 0;
    const offsets: Record<string, string> = {
      '--ds-site-header-height': `${bar.offsetHeight}px`,
      '--ds-site-header-drawer-top': `${Math.max(barRect.top, 0)}px`,
      '--ds-site-header-drawer-start': `${start(barRect) + inset}px`,
    };
    const button = menuButtonRef.current?.getBoundingClientRect();
    if (button && button.width > 0) {
      offsets['--ds-site-header-close-top'] = `${button.top}px`;
      offsets['--ds-site-header-close-start'] = `${start(button)}px`;
    }
    setDrawerOffset(offsets as React.CSSProperties);
  }, []);

  // Once before the first frame, so the drawer never paints unplaced.
  useLayoutEffect(() => {
    if (!drawerOpen) {
      // A host that closes a controlled drawer itself never calls setDrawerOpen.
      lockedGutter.current = 0;
      return;
    }
    placeDrawer();
  }, [drawerOpen, placeDrawer]);

  // And once more after the drawer's scroll lock engages (a child's effect,
  // so it has run by the time this one does): taking the scrollbar away
  // widens the page and moves the menu button by the scrollbar's width,
  // which the first measurement could not see. The close button fades in
  // only once the panel has slid home, so the correction never shows.
  useEffect(() => {
    if (drawerOpen) placeDrawer();
  }, [drawerOpen, placeDrawer]);

  const openSection = useCallback((id: string) => {
    clearTimeout(closeTimer.current);
    setOpenId(id);
    setShownId(id);
  }, []);

  const scheduleClose = useCallback(() => {
    clearTimeout(closeTimer.current);
    closeTimer.current = setTimeout(() => setOpenId(null), MOTION_HOVER_HIDE_DELAY_MS);
  }, []);

  const closePanel = useCallback(() => {
    clearTimeout(closeTimer.current);
    setOpenId(null);
  }, []);

  const triggerFor = (id: string) =>
    navRef.current?.querySelector<HTMLElement>(`[data-section="${CSS.escape(id)}"]`) ?? null;

  // The open panel is a light-dismiss layer: an outside press or Escape
  // closes it through the shared stack, and Escape hands focus back to the
  // pill that opened it.
  useLayer({
    open: openId != null && !folded,
    onDismiss: () => {
      const trigger = openId ? triggerFor(openId) : null;
      const focusInPanel = panelRef.current?.contains(document.activeElement) ?? false;
      closePanel();
      if (focusInPanel && trigger) {
        returningFocus.current = true;
        trigger.focus();
        returningFocus.current = false;
      }
    },
    dismissOnOutsidePress: true,
    getElements: () => [navRef.current, panelRef.current],
  });

  // A fold closes any open panel; the drawer takes over.
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    if (folded) setOpenId(null);
    // Only a measured unfold closes the drawer: on mount `folded` is false
    // until the first measurement, and a drawer opened from the start
    // (`defaultDrawerOpen`, or a controlled `drawerOpen`) must survive that.
    else if (measured && drawerOpen) setDrawerOpen(false);
  }, [folded, measured, drawerOpen, setDrawerOpen]);

  const panelOpen = openId != null && sections.some((s) => s.id === openId && s.mega);
  const shown = sections.find((s) => s.id === shownId && s.mega) ?? null;

  // The open menu's height, so the backdrop a full-width bar lays behind it
  // (see SiteHeader.css) reaches past the menu's bottom edge before it fades.
  // Measured as the menu opens and as it changes size (another section's
  // menu, a wrapped description), straight onto the header's style, so a
  // resize never renders React.
  useLayoutEffect(() => {
    const header = headerRef.current;
    const panel = panelRef.current;
    if (!header || !panel || !panelOpen) return;
    const write = () => {
      header.style.setProperty('--ds-site-header-menu-height', `${panel.offsetHeight}px`);
      // Where the section pills start, from the bar's inline start, so a
      // full bar's menu opens under them rather than centred on the window.
      const bar = barRef.current;
      const nav = navRef.current;
      if (bar && nav) {
        const barRect = bar.getBoundingClientRect();
        const navRect = nav.getBoundingClientRect();
        const start = isRtl(bar) ? barRect.right - navRect.right : navRect.left - barRect.left;
        header.style.setProperty('--ds-site-header-nav-start', `${Math.round(start)}px`);
      }
    };
    write();
    const observer = new ResizeObserver(write);
    observer.observe(panel);
    return () => observer.disconnect();
  }, [panelOpen, shownId]);

  // The drawer is a stack: the sections first and large, each with pages
  // drilling into its own level, then whatever the host adds below them.
  const toDrawerRow = (item: SiteHeaderDrawerItem): NavStackItem => ({
    label: item.label,
    href: item.href,
    description: item.description,
    icon: item.icon,
    ...(item.items?.length ? { id: item.href, items: item.items.map(toDrawerRow) } : {}),
  });
  const drawerStack: NavStackEntry[] = [
    {
      type: 'section',
      id: 'sections',
      items: sections.map((section) => {
        const pages = section.drawerItems ?? section.mega?.items ?? [];
        return {
          id: section.id,
          label: section.label,
          href: section.href,
          current: sectionIsCurrent(section, currentHref) || undefined,
          ...(pages.length > 0 ? { items: pages.map(toDrawerRow) } : {}),
        };
      }),
    },
    ...(drawerEntries ?? []),
  ];
  // The stack opens on the level that holds the current page, so a reader
  // deep in a section reopens the menu where they are.
  const drawerOpenPath = navStackPathTo(drawerStack, currentHref);
  const drawerOnFirstLevel = (drawerDepth ?? drawerOpenPath.length) === 0;

  const classes = [
    baseClass,
    sticky && `${baseClass}--sticky`,
    width && `${baseClass}--width`,
    condensed && `${baseClass}--condensed`,
    folded && `${baseClass}--folded`,
    !measured && initialFold !== 'never' && `${baseClass}--prefold-${initialFold}`,
    className,
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <header {...rest} ref={setRef} className={classes} data-ds-width={width}>
      {sticky && <ProgressiveBlur className={`${baseClass}__blur`} tinted={tinted} />}
      {/* Behind an open menu on a full-width bar: the window's width, from
          the top to past the menu, fading out below (SiteHeader.css shows
          it only in that mode). */}
      <ProgressiveBlur
        className={`${baseClass}__menu-blur`}
        tinted
        data-open={panelOpen && !folded ? '' : undefined}
      />

      <div ref={barRef} className={`${baseClass}__bar`}>
        {brand && (
          <div ref={brandRef} className={`${baseClass}__brand`}>
            {brand}
          </div>
        )}

        <nav ref={navRef} aria-label={navLabel} className={`${baseClass}__nav`} inert={folded}>
          {sections.map((section) => {
            const current = sectionIsCurrent(section, currentHref);
            const open = openId === section.id;
            const pillClass = [
              `${baseClass}__pill`,
              open && `${baseClass}__pill--open`,
              current && `${baseClass}__pill--current`,
            ]
              .filter(Boolean)
              .join(' ');

            if (!section.mega) {
              return (
                <Link
                  key={section.id}
                  href={section.href}
                  data-section={section.id}
                  className={pillClass}
                  aria-current={current ? 'page' : undefined}
                  onMouseEnter={scheduleClose}
                  onClick={closePanel}
                >
                  {section.label}
                </Link>
              );
            }

            return (
              <div
                key={section.id}
                className={`${baseClass}__section`}
                onMouseEnter={() => openSection(section.id)}
                onMouseLeave={scheduleClose}
              >
                <Link
                  href={section.href}
                  data-section={section.id}
                  className={pillClass}
                  aria-current={current ? 'page' : undefined}
                  aria-expanded={open}
                  aria-controls={panelId}
                  onFocus={() => {
                    if (!returningFocus.current) openSection(section.id);
                  }}
                  onClick={closePanel}
                  onKeyDown={(event: React.KeyboardEvent<HTMLAnchorElement>) => {
                    // ArrowDown steps into the open panel, so its links are
                    // one key away rather than past every pill and action.
                    if (event.key !== 'ArrowDown') return;
                    event.preventDefault();
                    openSection(section.id);
                    requestAnimationFrame(() => panelRef.current?.querySelector<HTMLElement>('a')?.focus());
                  }}
                >
                  <span>{section.label}</span>
                  <span
                    className={`material-symbols-rounded ${baseClass}__caret`}
                    aria-hidden="true"
                  >
                    expand_more
                  </span>
                </Link>
              </div>
            );
          })}
        </nav>

        <div className={`${baseClass}__end`}>
          {actions && (
            <div ref={actionsRef} className={`${baseClass}__actions`} inert={condensed}>
              {actions}
            </div>
          )}
          {condensedActions && (
            <div
              ref={condensedActionsRef}
              className={`${baseClass}__actions ${baseClass}__actions--condensed`}
              inert={!condensed}
            >
              {condensedActions}
            </div>
          )}
          {wideActions && (
            <div ref={wideRef} className={`${baseClass}__wide-actions`} inert={folded}>
              {wideActions}
            </div>
          )}
          <IconButton
            ref={menuButtonRef}
            className={[`${baseClass}__menu-button`, drawerOpen && `${baseClass}__menu-button--hidden`]
              .filter(Boolean)
              .join(' ')}
            icon="menu"
            size="compact"
            variant="secondary"
            tone="neutral"
            label={drawerOpenLabel}
            tooltip={false}
            aria-expanded={drawerOpen}
            aria-haspopup="dialog"
            onClick={() => setDrawerOpen(true)}
          />
        </div>

        <div
          className={`${baseClass}__panel`}
          onMouseEnter={() => openId && openSection(openId)}
          onMouseLeave={scheduleClose}
        >
          <MegaMenu
            ref={panelRef}
            id={panelId}
            open={panelOpen && !folded}
            items={shown?.mega?.items ?? []}
            showcase={shown?.mega?.showcase}
            currentHref={currentHref}
            linkComponent={Link}
            onNavigate={closePanel}
          />
        </div>
      </div>

      <Drawer
        open={drawerOpen}
        onOpenChange={setDrawerOpen}
        title={drawerTitle}
        closeLabel={drawerCloseLabel}
        side="start"
        size="sm"
        footer={drawerOnFirstLevel ? drawerFooter : undefined}
        className={`${baseClass}__drawer`}
        style={drawerOffset}
        heading={
          brand && (
            <div
              className={`${baseClass}__drawer-brand`}
              onClick={(event) => {
                // The brand usually links home: following it closes the drawer.
                if ((event.target as HTMLElement).closest('a')) setDrawerOpen(false);
              }}
            >
              {brand}
            </div>
          )
        }
      >
        <NavStack
          key={drawerOpen ? 'open' : 'closed'}
          items={drawerStack}
          header={drawerHeader}
          currentHref={currentHref}
          defaultPath={drawerOpenPath}
          navLabel={navLabel}
          linkComponent={Link}
          onNavigate={() => setDrawerOpen(false)}
          onPathChange={(path) => setDrawerDepth(path.length)}
        />
      </Drawer>
    </header>
  );
}
